import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';

const out = path.join(process.env.TEMP, 'code-bug6944-real.png');

http.get('http://localhost:8167/api/v2.0/code', (res) => {
  let d = '';
  res.on('data', (c) => (d += c));
  res.on('end', () => {
    const j = JSON.parse(d);
    fs.writeFileSync(out, Buffer.from(j.data, 'base64'));
    console.log(JSON.stringify({ path: out, uuid: j.uuid }));
  });
}).on('error', (e) => {
  console.error(e);
  process.exit(1);
});

